class Solution {
    public int jump(int[] nums) {
        if (nums.length <= 1) {
            return 0;
        }
        int jumps = 0;
        int currentEnd = 0;
        int farthest = 0;
        for (int i = 0; i < nums.length - 1; i++) {
            farthest = Math.max(farthest, i + nums[i]);
            if (i == currentEnd) {
                jumps++;
                currentEnd = farthest;
                if (currentEnd >= nums.length - 1) {
                    break;
                }
            }
        }
        return jumps;
    }
}

class Solution {
    public int jump(int[] nums) {
        int n = nums.length;
        int[] dp = new int[n];
        java.util.Arrays.fill(dp, 1_000_000);
        dp[0] = 0;
        for (int i = 0; i < n; i++) {
            if (dp[i] == 1_000_000) {
                continue;
            }
            int farthest = Math.min(n - 1, i + nums[i]);
            for (int next = i + 1; next <= farthest; next++) {
                dp[next] = Math.min(dp[next], dp[i] + 1);
            }
        }
        return dp[n - 1];
    }
}

class Solution {
    public int jump(int[] nums) {
        int[] memo = new int[nums.length];
        java.util.Arrays.fill(memo, -1);
        return solve(nums, 0, memo);
    }

    private int solve(int[] nums, int index, int[] memo) {
        if (index >= nums.length - 1) {
            return 0;
        }
        if (memo[index] != -1) {
            return memo[index];
        }
        int best = 1_000_000;
        int farthest = Math.min(nums.length - 1, index + nums[index]);
        for (int next = index + 1; next <= farthest; next++) {
            best = Math.min(best, 1 + solve(nums, next, memo));
        }
        memo[index] = best;
        return best;
    }
}

class Solution {
    public int jump(int[] nums) {
        int n = nums.length;
        int[] dp = new int[n];
        java.util.Arrays.fill(dp, 1_000_000);
        dp[n - 1] = 0;
        for (int i = n - 2; i >= 0; i--) {
            int farthest = Math.min(n - 1, i + nums[i]);
            int best = 1_000_000;
            for (int next = i + 1; next <= farthest; next++) {
                best = Math.min(best, 1 + dp[next]);
            }
            dp[i] = best;
        }
        return dp[0];
    }
}

class Solution {
    public int jump(int[] nums) {
        int n = nums.length;
        if (n == 1) {
            return 0;
        }
        int[] dp = new int[n];
        java.util.PriorityQueue<int[]> active = new java.util.PriorityQueue<>((a, b) -> Integer.compare(a[0], b[0]));
        active.offer(new int[]{0, nums[0]});
        for (int i = 1; i < n; i++) {
            while (!active.isEmpty() && active.peek()[1] < i) {
                active.poll();
            }
            dp[i] = active.peek()[0] + 1;
            active.offer(new int[]{dp[i], i + nums[i]});
        }
        return dp[n - 1];
    }
}
